#pragma once

#include <array>
#include <cstddef>
#include <string>
#include <vector>

#include "binaural/point_source.h"
#include "binaural/reference_distance.h"
#include "binaural/room_tables.h"
#include "binaural/shoebox_room.h"
#include "foundation/status.h"
#include "hrtf/full_hrir_field.h"
#include "hrtf/partitioned_convolution.h"

// Optional coupling of the SOFA direct path to this project's own room: six
// first-order image sources rendered through the same HRIR field, plus the late
// FDN tail.  Ported from the reference src/sofa_room.py; the room is generated by
// this project's own model (see room_tables.h), not a measured BRIR.
namespace joc::binaural {

inline constexpr std::size_t kSofaRoomBatchSamples = 1536;

class SofaRoom {
public:
    Status configure(std::size_t source_count, const PointSourceReference& reference,
                     int implementation_latency, int recording_origin,
                     const std::string& preset);

    bool active() const { return valid_; }
    const std::string& preset() const { return preset_; }
    double rt60_seconds() const { return rt60_seconds_; }

    // Sends for one source; `state` is null for the LFE channel.
    Status set_source(std::size_t source, const PointSourcePosition* state, double gain,
                      bool first, bool special_lfe);

    Status radians_paths(const PointSourcePosition& state,
                         std::vector<EarlyReflection>* paths);
    double direct_gain(const PointSourcePosition& state) const;
    double early_gain(const EarlyReflection& reflection, double measurement_radius_m) const;
    const ShoeboxRoomConfig& early_config() const { return config_; }
    double early_delay_bound_samples() const;
    double maximum_early_delay_samples() const { return maximum_early_delay_samples_; }

    // HRIR of the direct sound plus the six first-order reflections.
    Status full_hrir(hrtf::FullHrirField& field, const PointSourcePosition& state,
                     std::size_t output_taps, std::vector<double>* hrir);
    std::size_t filter_budget(const hrtf::FullHrirField& field) const;

    // One 128-sample block: returns false while the 1536-sample batch is filling.
    Status process(const double* block, std::size_t sources, const double* direct,
                   std::vector<double>* out, bool* produced);

    std::size_t pending_samples() const { return pending_blocks_ * 128u; }
    // Clears the send state and the pending batch but keeps the loaded room.
    void reset();

private:
    void distance_state(const PointSourcePosition& state, DistanceState* out) const;

    bool valid_ = false;
    std::string preset_;
    PointSourceReference reference_;
    ShoeboxRoomConfig config_;
    double rt60_seconds_ = 0.0;
    double alignment_samples_ = 0.0;
    hrtf::UniformPartitionedConvolver convolver_;
    std::vector<double> current_;
    std::vector<double> target_;
    std::vector<double> pending_mono_;
    std::vector<double> pending_direct_;
    std::size_t pending_blocks_ = 0;
    double maximum_early_delay_samples_ = 0.0;
};

}  // namespace joc::binaural
